// Agent defines model for Agent.
type Agent struct {
	ActiveVersion *int                `json:"active_version,omitempty"`
	CreatedAt     *time.Time          `json:"created_at,omitempty"`
	Description   *string             `json:"description,omitempty"`
	Id            *openapi_types.UUID `json:"id,omitempty"`
	LatestVersion *int                `json:"latest_version,omitempty"`
	Name          string              `json:"name"`
	ProjectId     *openapi_types.UUID `json:"project_id,omitempty"`
	Slug          string              `json:"slug"`
	Status        AgentStatus         `json:"status"`
	UpdatedAt     *time.Time          `json:"updated_at,omitempty"`
}

// AgentConfig Cấu hình bất biến của một Agent Version. Xem docs/architecture/agent-runtime.md §3
type AgentConfig struct {
	Delegation *struct {
		// CanDelegateTo Agent (cùng project) mà Agent này được giao việc cho, bằng tool nội bộ
		// `delegate_task`. Agent đích chạy version đang hoạt động của nó lúc execution được
		// tạo. Mỗi lần giao việc còn được quyết định lại lúc chạy: Agent đích không phải tổ
		// tiên trong chuỗi giao việc, độ sâu, tổng số task của execution (16), và budget
		// (lấy từ phần còn lại của task giao việc).
		CanDelegateTo *[]openapi_types.UUID `json:"can_delegate_to,omitempty"`

		// MaxDepth Độ sâu tối đa của chuỗi giao việc bắt đầu từ execution (task gốc ở độ sâu 0).
		// Phải từ 1 trở lên khi có `can_delegate_to`. Giới hạn nhỏ nhất trong chuỗi được áp.
		MaxDepth *int `json:"max_depth,omitempty"`
	} `json:"delegation,omitempty"`
	Limits struct {
		Budget         *Money `json:"budget,omitempty"`
		MaxIterations  int    `json:"max_iterations"`
		MaxToolCalls   int    `json:"max_tool_calls"`
		TimeoutSeconds int    `json:"timeout_seconds"`
	} `json:"limits"`
	Memory *struct {
		SessionHistory *AgentConfigMemorySessionHistory `json:"session_history,omitempty"`
	} `json:"memory,omitempty"`
	Model struct {
		DefaultTier     *ModelTier          `json:"default_tier,omitempty"`
		FixedModelId    *openapi_types.UUID `json:"fixed_model_id,omitempty"`
		MaxOutputTokens *int                `json:"max_output_tokens,omitempty"`

		// Policy `fixed`: luôn dùng `fixed_model_id`. `tiered`: Model Router chọn chuỗi model của `default_tier` theo cấu hình `model_routing` của project / organization lúc tạo execution.
		Policy      AgentConfigModelPolicy `json:"policy"`
		Temperature *float32               `json:"temperature,omitempty"`
	} `json:"model"`
	Role    *string `json:"role,omitempty"`
	Runtime *struct {
		Isolation *AgentConfigRuntimeIsolation `json:"isolation,omitempty"`
	} `json:"runtime,omitempty"`
	Tools []struct {
		// Allow Tên tool; `*` cho tất cả
		Allow           []string                         `json:"allow"`
		Deny            *[]string                        `json:"deny,omitempty"`
		RequireApproval *AgentConfigToolsRequireApproval `json:"require_approval,omitempty"`
		ServerId        openapi_types.UUID               `json:"server_id"`
	} `json:"tools"`
}

