// WorkflowDefinition Định nghĩa của một workflow (ADR-0015): một đồ thị không chu trình các bước. Mỗi lần chạy
// được biên dịch thành một execution `planned`, nên các trần của `planned` áp dụng: tối đa
// 16 bước, chuỗi phụ thuộc dài tối đa 8, mỗi bước `agent` phải có budget (của bước hoặc của
// Agent Version). Không có biến hay template: một bước `agent` chỉ nhận `goal` của nó và
// tóm tắt kết quả của các bước `agent` nó phụ thuộc trực tiếp. Định nghĩa được kiểm khi
// ghi và kiểm lại (Agent còn hoạt động, model, giá, budget) ở mỗi lần chạy. Bước `tool`
// chưa hỗ trợ.
//
// Bước `approval` là một cổng chờ người: lần chạy dừng ở bước đó (`waiting_approval`) tới
// khi đủ `required_approvals` người duyệt (bước hoàn thành), có người từ chối hoặc hết
// `timeout_seconds` (bước thất bại; các bước sau theo `on_failure`). Approval của bước
// hiện ở `/v1/approvals` với `subject_type: workflow_step`. Người yêu cầu là người chạy
// lần đó (với lần chạy theo lịch: người chạy của workflow) và không tự duyệt được; người
// đã viết `definition` của lần chạy (hoặc người tạo API key đã viết nó) cũng không.
// Approval không sống quá hạn của execution. Bước `approval` không nhận
// `on_failure: continue`, và một bước đứng sau cổng chưa được duyệt (kể cả gián tiếp)
// không chạy.
type WorkflowDefinition struct {
	// MaxParallelSteps Số bước chạy đồng thời; không vượt cấu hình của project
	MaxParallelSteps *int `json:"max_parallel_steps,omitempty"`
	Steps            []struct {
		// AgentId Với `agent`
		AgentId *openapi_types.UUID `json:"agent_id,omitempty"`

		// Budget Với `agent`. Chỉ được chặt hơn `limits.budget` của Agent Version
		Budget    *Money    `json:"budget,omitempty"`
		DependsOn *[]string `json:"depends_on,omitempty"`

		// Goal Với `agent`. Việc giao cho Agent
		Goal *string `json:"goal,omitempty"`
		Id   string  `json:"id"`

		// MaxAttempts Với `agent`: số lần chạy bước. Bước được chạy lại khi nó kết thúc `failed` hoặc `timed_out` (không chạy lại khi hết budget hay bị huỷ). Mỗi lần thử là một task riêng của execution (`<id>`, `<id>-try2`, `<id>-try3`), tính vào trần 16 bước, có budget riêng bằng budget của bước (chi phí xấu nhất của bước là `max_attempts` × budget của nó) và thời hạn riêng, và tính vào độ dài chuỗi phụ thuộc (tối đa 8). Bước CHỈ được chạy lại khi các lần thử trước chắc chắn chưa gây tác động: không gọi tool nào ngoài tool chỉ đọc (kể cả lời gọi có kết quả không xác định) và không giao việc cho Agent khác; ngược lại lần thử lại kết thúc `failed` mà không chạy. Lần thử lại thấy tóm tắt kết quả của lần thử trước. `on_failure` áp cho kết quả của lần thử cuối cùng đã chạy; bước sau nhận kết quả của lần thử thành công.
		MaxAttempts *int `json:"max_attempts,omitempty"`

		// Message Với `approval`. Điều người duyệt được hỏi (văn bản tĩnh)
		Message   *string                           `json:"message,omitempty"`
		OnFailure *WorkflowDefinitionStepsOnFailure `json:"on_failure,omitempty"`

		// RequiredApprovals Với `approval`. Số người duyệt (khác nhau) cần có
		RequiredApprovals *int `json:"required_approvals,omitempty"`

		// Seconds Với `wait`. Thời gian chờ
		Seconds *int `json:"seconds,omitempty"`

		// TimeoutSeconds Với `approval`: thời hạn duyệt (60–86400 giây, mặc định 1800); hết hạn là từ chối. Với `agent`: thời hạn riêng của bước (từ 10 giây), chỉ được chặt hơn thời hạn của Agent Version; quá hạn thì bước kết thúc `timed_out` và các bước sau theo `on_failure`.
		TimeoutSeconds *int                        `json:"timeout_seconds,omitempty"`
		Type           WorkflowDefinitionStepsType `json:"type"`
	} `json:"steps"`
}

